#pragma once
static HWND savedPlacesRoot(HWND window){return window?GetAncestor(window,GA_ROOTOWNER):nullptr;}
static void updateSelectedSavedLabel(){
    bool savedOrigin=gSelectedPlaceOrigin==L"已收藏的位置"||gSelectedPlaceOrigin==L"Saved location"||gSelectedPlaceOrigin==L"已移除收藏的位置"||gSelectedPlaceOrigin==L"Previously saved location";if(!savedOrigin||gCol<0)return;
    int index=savedPlaces::find(gSavedPlaces,gSelectedLatitude,gSelectedLongitude);if(index>=0){gSelectedPlaceTitle=gSavedPlaces[index].name;gSelectedPlaceOrigin=gEnglish?L"Saved location":L"已收藏的位置";}else gSelectedPlaceOrigin=gEnglish?L"Previously saved location":L"已移除收藏的位置";
}
static bool syncSavedPlacesFromDisk(HWND window){
    std::vector<savedPlaces::Place> latest;bool valid=savedPlaces::load(savedPlacesPath(),latest),oldBad=gSavedPlacesUnreadable;gSavedPlacesUnreadable=!valid;
    if(valid&&!savedPlaces::sameCollection(latest,gSavedPlaces)){gSavedPlaces.swap(latest);updateSelectedSavedLabel();syncExperienceControls();refreshUnifiedSavedResults();if(window)InvalidateRect(window,&gInfoRect,FALSE);return true;}if(oldBad!=gSavedPlacesUnreadable)refreshUnifiedSavedResults();return false;
}
static std::wstring savedPlaceStatus(savedPlaces::Status status){switch(status){
    case savedPlaces::Status::Busy:return gEnglish?L"Saved places are being updated in another window. Try again shortly.":L"另一个窗口正在更新收藏，请稍后重试。";
    case savedPlaces::Status::Unreadable:return gEnglish?L"The saved file could not be read. The original file has been preserved.":L"收藏文件无法读取，原文件已保留，未覆盖。";
    case savedPlaces::Status::Full:return gEnglish?L"Up to 64 places can be saved. Remove one first.":L"最多收藏64个位置，请先移除不需要的位置。";
    case savedPlaces::Status::Missing:return gEnglish?L"This place was removed in another window.":L"这个收藏已在另一个窗口移除。";
    case savedPlaces::Status::Conflict:return gEnglish?L"The name changed in another window; that newer name has been kept.":L"另一个窗口已更新名称，已保留较新的名称。";
    case savedPlaces::Status::Invalid:return gEnglish?L"Enter a name of 1–120 characters.":L"请输入1至120字的名称。";
    default:return gEnglish?L"Unable to save. The previous file has been preserved.":L"保存失败，原有收藏文件已保留。";
}}
static bool applySavedPlaceChange(HWND window,const savedPlaces::Request& request,bool remember){
    auto result=savedPlaces::update(savedPlacesPath(),request);gLastSavedPlaceStatus=result.status;if(result.snapshot)gSavedPlaces=result.places;if(result.status==savedPlaces::Status::Unreadable)gSavedPlacesUnreadable=true;else if(result.snapshot)gSavedPlacesUnreadable=false;
    bool success=result.status==savedPlaces::Status::Changed||result.status==savedPlaces::Status::Unchanged;
    if(result.status==savedPlaces::Status::Changed&&remember&&result.hadPrevious){savedPlaces::Undo undo;if(request.operation==savedPlaces::Operation::Remove)undo={savedPlaces::Operation::Add,result.previous,L""};else if(request.operation==savedPlaces::Operation::Rename)undo={savedPlaces::Operation::Rename,result.previous,request.place.name};else undo={savedPlaces::Operation::Remove,request.place,L""};if(gSavedPlacesUndo.size()==16)gSavedPlacesUndo.erase(gSavedPlacesUndo.begin());gSavedPlacesUndo.push_back(undo);}
    if(success){if(request.operation==savedPlaces::Operation::Add)gNotice=gEnglish?L"Place saved on this computer":L"已将位置收藏在本机";else if(request.operation==savedPlaces::Operation::Remove)gNotice=gEnglish?L"Place removed · Undo is available in Saved":L"已移除收藏，可在“收藏”中撤销";else gNotice=gEnglish?L"Saved place renamed":L"已更新收藏名称";}else gNotice=savedPlaceStatus(result.status);
    updateSelectedSavedLabel();syncExperienceControls();refreshUnifiedSavedResults();HWND root=savedPlacesRoot(window);if(root)InvalidateRect(root,nullptr,FALSE);if(gUnifiedSearchWindow&&IsWindow(gUnifiedSearchWindow))SetWindowTextW(GetDlgItem(gUnifiedSearchWindow,2304),gNotice.c_str());return success;
}
static void removeSavedPlace(HWND window,const savedPlaces::Place& place){applySavedPlaceChange(window,{savedPlaces::Operation::Remove,place,L""});}
static void undoSavedPlace(HWND window){if(gSavedPlacesUndo.empty())return;auto undo=gSavedPlacesUndo.back();if(applySavedPlaceChange(window,{undo.operation,undo.place,undo.expectedName},false)){gSavedPlacesUndo.pop_back();gNotice=gEnglish?L"Saved-place change undone":L"已撤销收藏改动";refreshUnifiedSavedResults();if(gUnifiedSearchWindow)SetWindowTextW(GetDlgItem(gUnifiedSearchWindow,2304),gNotice.c_str());}else if(gLastSavedPlaceStatus==savedPlaces::Status::Conflict||gLastSavedPlaceStatus==savedPlaces::Status::Missing){gSavedPlacesUndo.pop_back();refreshUnifiedSavedResults();if(gUnifiedSearchWindow)SetWindowTextW(GetDlgItem(gUnifiedSearchWindow,2304),gNotice.c_str());}}
